# name: shared_feature_competitor_choice_rate
# description: Rate of choosing a non-minimal word-true referent on heard-word trials where a single-feature word-true referent competes against multi-feature word-true referents that share additional non-heard features with other objects in the display.
def test_statistic(df):
    scenes = df[["objects", "heard"]].drop_duplicates()
    target_map = {}
    for objs_str, heard in zip(scenes["objects"], scenes["heard"]):
        if pd.isna(heard):
            continue
        h = int(heard)
        objs = json.loads(objs_str)
        n_feat = len(objs[0])
        true_idxs = [i for i, o in enumerate(objs) if o[h] == 1]
        dups = [sum(1 for o2 in objs if o2 == objs[i]) for i in range(len(objs))]
        fcs = [sum(o) for o in objs]
        single_feat_sing = [i for i in true_idxs if fcs[i] == 1 and dups[i] == 1]
        if not single_feat_sing:
            continue
        # Check for multi-feature word-true referents whose non-heard features are shared with at least one other object
        non_min = []
        for i in true_idxs:
            if fcs[i] > 1:
                other_feats = [f for f in range(n_feat) if f != h and objs[i][f] == 1]
                # Check if at least one non-heard feature of i is shared by another object in the scene
                if any(sum(objs[j][f] for j in range(len(objs))) > 1 for f in other_feats):
                    non_min.append(i)
        if non_min and all(dups[i] == 1 for i in single_feat_sing):
            target_map[(objs_str, h)] = set(non_min)
    if not target_map:
        return 0.0
    valid = df["heard"].notna()
    sub = df[valid]
    keys = list(zip(sub["objects"], sub["heard"].astype(int)))
    targets = [target_map.get(k) for k in keys]
    mask = [t is not None for t in targets]
    if not any(mask):
        return 0.0
    choices = sub["choice"].to_numpy()[mask]
    active_targets = [t for t in targets if t is not None]
    hits = [1.0 if c in t else 0.0 for c, t in zip(choices, active_targets)]
    return float(np.mean(hits))

# name: prior_duplicated_referent_choice_rate
# description: Rate of choosing a duplicated (non-unique) object on wordless prior trials (`heard` is NaN) in scenes that contain both unique (singleton) and duplicated objects.
def test_statistic(df):
    scenes = df[df["heard"].isna()][["objects"]].drop_duplicates()
    target_map = {}
    for objs_str in scenes["objects"]:
        objs = json.loads(objs_str)
        dups = [sum(1 for o2 in objs if o2 == objs[i]) for i in range(len(objs))]
        dup_idxs = [i for i, d in enumerate(dups) if d > 1]
        sing_idxs = [i for i, d in enumerate(dups) if d == 1]
        if dup_idxs and sing_idxs:
            target_map[objs_str] = set(dup_idxs)
    if not target_map:
        return 0.0
    sub = df[df["heard"].isna()]
    targets = [target_map.get(o) for o in sub["objects"]]
    mask = [t is not None for t in targets]
    if not any(mask):
        return 0.0
    choices = sub["choice"].to_numpy()[mask]
    active_targets = [t for t in targets if t is not None]
    hits = [1.0 if c in t else 0.0 for c, t in zip(choices, active_targets)]
    return float(np.mean(hits))

# name: two_true_referents_more_features_choice_rate
# description: Rate of choosing the more feature-rich word-true referent on heard-word trials where the heard word is true of exactly two objects and those two objects differ in their total number of features.
def test_statistic(df):
    scenes = df[["objects", "heard"]].drop_duplicates()
    target_map = {}
    for objs_str, heard in zip(scenes["objects"], scenes["heard"]):
        if pd.isna(heard):
            continue
        h = int(heard)
        objs = json.loads(objs_str)
        true_idxs = [i for i, o in enumerate(objs) if o[h] == 1]
        if len(true_idxs) == 2:
            fc0, fc1 = sum(objs[true_idxs[0]]), sum(objs[true_idxs[1]])
            if fc0 != fc1:
                rich_idx = true_idxs[0] if fc0 > fc1 else true_idxs[1]
                target_map[(objs_str, h)] = rich_idx
    if not target_map:
        return 0.0
    valid = df["heard"].notna()
    sub = df[valid]
    keys = list(zip(sub["objects"], sub["heard"].astype(int)))
    targets = [target_map.get(k) for k in keys]
    mask = [t is not None for t in targets]
    if not any(mask):
        return 0.0
    choices = sub["choice"].to_numpy()[mask]
    active_targets = np.array([t for t in targets if t is not None])
    return float(np.mean(choices == active_targets))

# name: singleton_same_feature_count_vs_duplicated_true
# description: Rate of choosing the unique (singleton) word-true referent on heard-word trials where a singleton word-true referent competes against a duplicated pair of word-true referents with the exact same total number of features.
def test_statistic(df):
    scenes = df[["objects", "heard"]].drop_duplicates()
    target_map = {}
    for objs_str, heard in zip(scenes["objects"], scenes["heard"]):
